from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _resolver(data, preference, name_order):
    packages = data["packages"]
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    names = sorted(packages, reverse=(name_order == "descending"))
    best = None
    best_vector = None

    def active_deps(row):
        return [d for d in row.get("deps", [])
                if not d.get("feature") or d["feature"] in features]

    def visit(assigned):
        nonlocal best, best_vector
        constraints = {name: [tuple(bounds)] for name, bounds in roots.items()}
        edges = {}
        for name, version in assigned.items():
            row = next(r for r in packages[name] if r["version"] == version)
            deps = active_deps(row)
            edges[name] = [d["name"] for d in deps]
            for d in deps:
                constraints.setdefault(d["name"], []).append((d["min"], d["max"]))

        for name, version in assigned.items():
            if any(not lo <= version <= hi for lo, hi in constraints.get(name, [])):
                return

        pending = [n for n in constraints if n not in assigned]
        if pending:
            name = pending[0]
            ranges = constraints[name]
            rows = [r for r in packages[name]
                    if all(lo <= r["version"] <= hi for lo, hi in ranges)
                    and r["version"] not in blocked.get(name, [])
                    and (name not in pins or r["version"] == pins[name])]
            rows.sort(key=lambda r: r["version"], reverse=(preference == "maximum"))
            for row in rows:
                child = assigned.copy()
                child[name] = row["version"]
                visit(child)
            return

        done, active = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not acyclic(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            done.add(name)
            return True

        if not all(acyclic(n) for n in edges):
            return
        vector = tuple(assigned.get(n, -1) for n in names)
        better = (best_vector is None or
                  (vector > best_vector if preference == "maximum" else vector < best_vector))
        if better:
            best_vector = vector
            best = assigned.copy()

    visit({})
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _build_resolver(preference, name_order):
    return lambda data: _resolver(data, preference, name_order)


SOLVERS = {
    "component_01": _build_resolver("maximum", "descending"),
    "component_02": _build_resolver("minimum", "descending"),
    "component_03": _build_resolver("maximum", "ascending"),
    "component_04": _build_resolver("minimum", "ascending"),
    "component_05": _build_resolver("maximum", "descending"),
}


def _component_06(data):
    def rounded(num, den):
        if data["rounding"] == "half_up":
            return (num + den // 2) // den
        return num // den

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    jobs = [j for j in data["jobs"] if j["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_ids = None
    best_value = None
    n = len(jobs)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        selected = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = sorted(j["id"] for j in selected)
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active = []
        valid = True
        for job in sorted(selected, key=lambda j: (j["start"], j["end"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(j["value"] for j in selected)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    import heapq

    required = data.get("required", [])
    bits = {node: sum(1 << i for i, r in enumerate(required) if r == node)
            for node in range(data["n"])}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source, start = data["source"], data["start"]
    initial = (source, bits[source], data["coupons"])
    distances = {initial: start}
    queue = [(start, source, bits[source], data["coupons"])]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = (edge["v"], mask | bits[edge["v"]], remaining)
                if arrival < distances.get(nxt, float("inf")):
                    distances[nxt] = arrival
                    heapq.heappush(queue, (arrival, *nxt))
    return {"arrival": None}


SOLVERS.update({
    "component_06": _component_06,
    "component_07": _component_07,
    "component_08": _component_08,
})
